use verity_direct::air::{self, ChainAir, ChainIdx, Layout, VuIo};
use verity_direct::challenger::FixedSerializingChallenger64;
use verity_direct::ctx::{modp, FieldKind, IntCtx};
use verity_direct::program::{chain_program, ChainIo, COL_CLAIM, COL_FIRST, COL_LAST, STEPS};
use verity_direct::stark::{self, BabyBearBackend, Backend, FriParams, GoldilocksBackend, DEFAULT_FRI};

fn arg(args: &[String], key: &str) -> Option<String> {
    args.iter().position(|a| a == key).and_then(|i| args.get(i + 1).cloned())
}

fn read_u16(p: &Path) -> Vec<u64> {
    fs::read(p).unwrap_or_else(|e| panic!("{}: {e}", p.display())).chunks_exact(2).map(|c| u16::from_le_bytes([c[0], c[1]]) as u64).collect()
}

/// The first `n` bases of `vu-k1536-neg` with their correct words (the committed negatives carry the operands; the
/// positives' arrays are not in git).
fn real_vus(root: &Path, n: usize) -> Vec<VuIo> {
    let k = 16 * STEPS as usize;
    let x = read_u16(&root.join("vu-k1536-neg.x.u16"));
    let w = read_u16(&root.join("vu-k1536-neg.w.u16"));
    let index: Value = serde_json::from_str(&fs::read_to_string(root.join("vu-k1536-neg.index.json")).unwrap()).unwrap();
    let cols: Vec<String> = index["columns"].as_array().unwrap().iter().map(|c| c.as_str().unwrap().to_string()).collect();
    let ci = cols.iter().position(|c| c == "correct_y").unwrap();
    let rows = index["rows"].as_array().unwrap();
    let mut out = vec![];
    for (i, r) in rows.iter().enumerate() {
        if out.len() == n { break; }
        if let Some(y) = r[ci].as_u64() {
            out.push(VuIo { x: x[i * k..(i + 1) * k].to_vec(), w: w[i * k..(i + 1) * k].to_vec(), y16: y });
        }
    }
    assert!(out.len() == n, "not enough real VUs with a correct word");
    out
}

// ---------------------------------------------------------------------------------------------------------------
// Row forging
// ---------------------------------------------------------------------------------------------------------------

struct Forge {
    kind: FieldKind,
    air: ChainAir,
    lay: Layout,
    zero_rows: Vec<Vec<i128>>,
}

impl Forge {
    fn new(kind: FieldKind) -> Self {
        let (air, lay) = ChainAir::new(kind);
        let (zero_rows, _, viol) = air::chain_rows(kind, lay.width, &air.idx, &air::zero_vu());
        assert!(viol.is_empty());
        Self { kind, air, lay, zero_rows }
    }
    fn idx(&self) -> &ChainIdx { &self.air.idx }
    fn p(&self) -> u128 { self.kind.prime() }

    /// One row from the lane's generator with the forger's values imposed on named hints.
    fn row(&self, io: &ChainIo, overrides: &[(&str, i128)]) -> Vec<i128> {
        let mut ctx = IntCtx::for_trace(self.kind);
        for (k, v) in overrides { ctx.overrides.insert(k.to_string(), *v); }
        chain_program(&mut ctx, io);
        assert_eq!(ctx.cols.len(), self.lay.width);
        ctx.cols
    }
    /// The 32-bit output word of a row (from its materialised column(s)).
    fn word(&self, row: &[i128]) -> u64 {
        let idx = self.idx();
        if idx.y.len() == 1 { modp(row[idx.y[0]], self.p()) } else { (modp(row[idx.y[0]], self.p()) << 16) | modp(row[idx.y[1]], self.p()) }
    }
    /// A VU's 96 honest rows chained from `c0`, optionally re-chained honestly from step `start` with word `c`.
    fn vu_rows(&self, vu: &VuIo, start: usize, c_at_start: u64) -> Vec<Vec<i128>> {
        let steps = STEPS as usize;
        let mut rows = Vec::with_capacity(steps);
        let mut c = 0u64;
        for s in 0..steps {
            if s == start { c = c_at_start; }
            let io = ChainIo { c, a: vu.x[16 * s..16 * s + 16].to_vec(), b: vu.w[16 * s..16 * s + 16].to_vec(), step: s as u64, y16: vu.y16 };
            let row = self.row(&io, &[]);
            c = self.word(&row);
            rows.push(row);
        }
        rows
    }
    fn honest(&self, vu: &VuIo) -> Vec<Vec<i128>> { self.vu_rows(vu, usize::MAX, 0) }
    fn claim_col(&self) -> usize { self.lay.col(COL_CLAIM) }

    /// The trace: real rows, then the zero VU tiled to the next power of two (as `chain_trace`).
    fn trace<G: PrimeField64>(&self, rows: &[Vec<i128>]) -> RowMajorMatrix<G> {
        let n = rows.len().max(2).next_power_of_two();
        let w = self.lay.width;
        let mut values: Vec<G> = Vec::with_capacity(n * w);
        for r in rows { values.extend(r.iter().map(|&v| G::from_canonical_u64(modp(v, self.p())))); }
        for i in rows.len()..n { values.extend(self.zero_rows[(i - rows.len()) % self.zero_rows.len()].iter().map(|&v| G::from_canonical_u64(modp(v, self.p())))); }
        RowMajorMatrix::new(values, w)
    }
    /// Failing named constraints over the real rows plus the first padding row (so the last real row's transition
    /// into the padding is evaluated too).
    fn failing<G: PrimeField64>(&self, rows: &[Vec<i128>]) -> Vec<(usize, String)> {
        let mut all: Vec<Vec<i128>> = rows.to_vec();
        all.push(self.zero_rows[0].clone());
        air::chain_failing_rows::<G>(self.kind, &self.air, &self.lay, &all, true)
    }
}

fn set_claim(forge: &Forge, row: &mut [i128], v: i128) { row[forge.claim_col()] = v; }

struct Case {
    id: String,
    expected: &'static str, // "reject" | "accept" | "accept_by_design"
    mechanism: String,
    mutation: String,
    rows: Vec<Vec<i128>>,
    verify_log_n: Option<usize>, // None: the trace's own height
}

fn cases(forge: &Forge, vus: &[VuIo]) -> Vec<Case> {
    let steps = STEPS as usize;
    let p = forge.p() as i128;
    let h0 = forge.honest(&vus[0]);
    let h1 = forge.honest(&vus[1]);
    let idx = forge.idx().clone();
    let mut out = vec![];
    let mut push = |id: &str, expected: &'static str, mechanism: &str, mutation: String, rows: Vec<Vec<i128>>, log_n: Option<usize>| {
        out.push(Case { id: id.into(), expected, mechanism: mechanism.into(), mutation, rows, verify_log_n: log_n });
    };

    let honest: Vec<Vec<i128>> = [h0.clone(), h1.clone()].concat();
    push("b_honest", "accept", "-", "two real VUs, untouched (control)".into(), honest.clone(), None);

    // (i) splice: VU 1 unit k takes c_in from VU 0's unit k-1 output; VU 1 re-chained honestly from there
    let k = 40;
    let c_sp = forge.word(&h0[k - 1]);
    let sp = forge.vu_rows(&vus[1], k, c_sp);
    let y_sp = forge.word(&sp[steps - 1]);
    let mut sp_rows = sp.clone();
    // the forger claims the spliced chain's word (honest epilogue for that word) -- regenerate the last row's claim
    let claimed = {
        let io = ChainIo { c: forge.word(&sp[steps - 2]), a: vus[1].x[16 * (steps - 1)..].to_vec(), b: vus[1].w[16 * (steps - 1)..].to_vec(), step: (steps - 1) as u64, y16: 0 };
        let r = forge.row(&io, &[]);
        let hi = if forge.lay.has("cast.hi") { forge.lay.col("cast.hi") } else { forge.lay.col("pack.y_hi") };
        modp(r[hi] + r[forge.lay.col("cast.carry")], forge.p())
    };
    for r in sp_rows.iter_mut() { set_claim(forge, r, claimed as i128); }
    push("b_splice", "reject", "vu.link (transition): (1-first')(c_in' - y) = 0 at VU 1 row k",
         format!("VU 1 unit {k}: c_in := VU 0's y_{} = {c_sp:#010x} (was {:#010x}); units {k}.. re-chained honestly (y32 {y_sp:#010x}); claim = cast {claimed:#06x}", k - 1, forge.word(&h1[k - 1])),
         [h0.clone(), sp_rows].concat(), None);

    // (ii) a 95-row VU: VU 0's row 95 dropped
    let mut r95 = h0[..steps - 1].to_vec();
    r95.extend(h1.iter().cloned());
    push("b_vu95_drop", "reject", "vu.next_first (transition): first' = last, with last = 0 at step 94",
         "VU 0's row 95 removed; VU 1 follows step 94 directly".into(), r95, None);
    // 95 rows with the last flag moved to step 94
    let mut r95f = h0[..steps - 1].to_vec();
    {
        let io = ChainIo { c: forge.word(&h0[steps - 3]), a: vus[0].x[16 * (steps - 2)..16 * (steps - 1)].to_vec(), b: vus[0].w[16 * (steps - 2)..16 * (steps - 1)].to_vec(), step: (steps - 2) as u64, y16: vus[0].y16 };
        let inv = verity_direct::ctx::inv_modp(94 - 95, forge.p());
        r95f[steps - 2] = forge.row(&io, &[(COL_LAST, 1), (COL_INV_NAME, inv)]);
    }
    r95f.extend(h1.iter().cloned());
    push("b_vu95_lastflag", "reject", "vu.last_key: last (step - 95) = 0 and vu.last_def: (step-95) inv = 1 - last",
         "VU 0 truncated to 95 rows with last := 1 on step 94 (inv honest for step 94)".into(), r95f, None);

    // a 97-row VU: VU 0's row 95 duplicated (second copy first = 0), then VU 1
    let mut r97 = h0.clone();
    r97.push(h0[steps - 1].clone());
    r97.extend(h1.iter().cloned());
    push("b_vu97_dup", "reject", "vu.next_first: after a last row the next row must have first = 1 (it has 0, step 95)",
         "VU 0's last row duplicated (97 rows)".into(), r97, None);
    // a 97-row VU: an extra row with step 96 after step 95 (first = 0, last = 0, inv honest)
    let mut r97s = h0.clone();
    {
        let io = ChainIo { c: forge.word(&h0[steps - 1]), a: vec![0; 16], b: vec![0; 16], step: 96, y16: vus[0].y16 };
        r97s.push(forge.row(&io, &[]));
    }
    r97s.extend(h1.iter().cloned());
    push("b_vu97_step96", "reject", "vu.next_first: the step-95 row has last = 1 so the next row needs first = 1 (step 96 row has first = 0)",
         "row with step = 96 appended to VU 0 (its own row-local constraints hold: last = 0, inv = (96-95)^-1)".into(), r97s, None);

    // step counter: skip, and a restart mid-VU
    let mut skip = honest.clone();
    {
        let io = ChainIo { c: forge.word(&h0[4]), a: vus[0].x[80..96].to_vec(), b: vus[0].w[80..96].to_vec(), step: 6, y16: vus[0].y16 };
        skip[5] = forge.row(&io, &[]);
    }
    push("b_step_skip", "reject", "vu.next_step (transition): (1-first')(step' - step - 1) = 0", "row 5 generated with step = 6 (inv, last honest for 6)".into(), skip, None);
    let mut restart = honest.clone();
    {
        let io = ChainIo { c: 0, a: vus[0].x[16 * 48..16 * 49].to_vec(), b: vus[0].w[16 * 48..16 * 49].to_vec(), step: 0, y16: vus[0].y16 };
        restart[48] = forge.row(&io, &[]);
        // re-chain the rest of VU 0 from the restarted word
        let mut c = forge.word(&restart[48]);
        for s in 49..steps {
            let io = ChainIo { c, a: vus[0].x[16 * s..16 * s + 16].to_vec(), b: vus[0].w[16 * s..16 * s + 16].to_vec(), step: s as u64, y16: vus[0].y16 };
            restart[s] = forge.row(&io, &[]);
            c = forge.word(&restart[s]);
        }
    }
    push("b_restart_mid_vu", "reject", "vu.next_first: row 47 has last = 0 so row 48 needs first = 0 (it has first = 1, step 0, c = 0)",
         "VU 0 restarted at row 48 (first = 1, step = 0, c_in = 0), rows 49..95 honest for the restarted chain".into(), restart, None);
    // a wrapped step counter is not a distinct field element: step = 95 + p is 95.  Recorded as an argument.

    // flag flips
    let mut ff = honest.clone();
    {
        let io = ChainIo { c: forge.word(&h0[49]), a: vus[0].x[16 * 50..16 * 51].to_vec(), b: vus[0].w[16 * 50..16 * 51].to_vec(), step: 50, y16: vus[0].y16 };
        ff[50] = forge.row(&io, &[(COL_FIRST, 1)]);
    }
    push("b_first_flip", "reject", "vu.first_step: first step = 0; vu.first_c: first c_in = 0; vu.next_first from row 49",
         "row 50: first := 1 with step 50 and the honest (non-zero) c_in".into(), ff, None);
    let mut lf = honest.clone();
    {
        let io = ChainIo { c: forge.word(&h0[49]), a: vus[0].x[16 * 50..16 * 51].to_vec(), b: vus[0].w[16 * 50..16 * 51].to_vec(), step: 50, y16: vus[0].y16 };
        lf[50] = forge.row(&io, &[(COL_LAST, 1)]);
    }
    push("b_last_flip", "reject", "vu.last_key: last (step - 95) = 0; vu.last_def", "row 50: last := 1 with step 50".into(), lf, None);
    let mut lz = honest.clone();
    {
        let io = ChainIo { c: forge.word(&h0[steps - 2]), a: vus[0].x[16 * (steps - 1)..].to_vec(), b: vus[0].w[16 * (steps - 1)..].to_vec(), step: 95, y16: vus[0].y16 };
        lz[steps - 1] = forge.row(&io, &[(COL_LAST, 0)]);
    }
    push("b_last_zero", "reject", "vu.last_def: (step-95) inv = 1 - last with step = 95 forces last = 1", "row 95: last := 0 (claim unbound)".into(), lz, None);

    // two VUs sharing a last row: VU 1's rows 0..94 then a copy of VU 0's last row
    let mut shared = h0.clone();
    shared.extend(h1[..steps - 1].iter().cloned());
    shared.push(h0[steps - 1].clone());
    push("b_shared_last", "reject", "vu.link: VU 0's last row has c_in = VU 0's y_94, not VU 1's y_94",
         "VU 1 = its rows 0..94 followed by VU 0's last row (its claim and epilogue are VU 0's)".into(), shared, None);

    // claim column
    let mut cm = honest.clone();
    let v = cm[steps - 1][forge.claim_col()];
    set_claim(forge, &mut cm[steps - 1], v ^ 1);
    push("b_claim_last", "reject", "vu.out: last (y16 - claim) = 0", format!("VU 0 last row claim {v:#06x} -> {:#06x}", v ^ 1), cm, None);
    let mut cf = honest.clone();
    for r in cf.iter_mut().take(steps - 1) { set_claim(forge, r, 0x1234); }
    push("b_claim_free_nonlast", "accept_by_design", "vu.claim is read only on last rows (PROTOCOL B 12.4)", "VU 0 rows 0..94: claim := 0x1234".into(), cf, None);

    // +p accumulator shadow (the BabyBear battery's `chain` class) at row 1 of VU 0
    let c1 = forge.word(&h0[0]);
    if forge.kind.small() {
        let shadow = c1 as i128 + p;
        let (hi, lo) = (shadow >> 16, shadow & 0xffff);
        let mut sh = honest.clone();
        let io = ChainIo { c: c1, a: vus[0].x[16..32].to_vec(), b: vus[0].w[16..32].to_vec(), step: 1, y16: vus[0].y16 };
        sh[1] = forge.row(&io, &[("x.c_hi", hi), ("x.c_lo", lo)]);
        push("b_shadow_plus_p", "reject", "vu.link[0]/[1] are limb-wise (c_hi' = y_hi, c_lo' = y_lo); x.c_hi range (16 bits) when c + p >= 2^32",
             format!("VU 0 row 1: x.c limbs := limbs of c_1 + p = {shadow:#x} (c_1 = {c1:#010x}); hi = {hi:#x}, lo = {lo:#x}; downstream hints honest for the limbs"), sh, None);
        // c_0 = p (== 0 mod p) as limbs on the first row
        let mut c0 = honest.clone();
        let io = ChainIo { c: 0, a: vus[0].x[..16].to_vec(), b: vus[0].w[..16].to_vec(), step: 0, y16: vus[0].y16 };
        c0[0] = forge.row(&io, &[("x.c_hi", p >> 16), ("x.c_lo", p & 0xffff)]);
        push("b_c0_shadow_p", "reject", "vu.first_c[0], vu.first_c[1]: first c_hi = first c_lo = 0 (limb-wise)",
             format!("VU 0 row 0: x.c limbs := limbs of p = ({:#x}, {:#x}), i.e. the word p == 0 (mod p)", p >> 16, p & 0xffff), c0, None);
    } else {
        // Goldilocks: c_1 + p is not a u64 and is the same field element as c_1: the shadow does not exist.  The
        // nearest witness is a non-word x.c = c_1 + 2^32 (a different element): Fp32Decode's ranges must reject it.
        let mut sh = honest.clone();
        let io = ChainIo { c: c1, a: vus[0].x[16..32].to_vec(), b: vus[0].w[16..32].to_vec(), step: 1, y16: vus[0].y16 };
        sh[1] = forge.row(&io, &[("x.c", c1 as i128 + (1i128 << 32))]);
        push("b_nonword_c", "reject", "x.c range (32-bit word) and vu.link", format!("VU 0 row 1: x.c := c_1 + 2^32 = {:#x}", c1 as i128 + (1i128 << 32)), sh, None);
        let mut c0 = honest.clone();
        let io = ChainIo { c: 0, a: vus[0].x[..16].to_vec(), b: vus[0].w[..16].to_vec(), step: 0, y16: vus[0].y16 };
        c0[0] = forge.row(&io, &[("x.c", 1i128 << 32)]);
        push("b_c0_nonword", "reject", "vu.first_c[0]: first c = 0; x.c range", "VU 0 row 0: x.c := 2^32".into(), c0, None);
    }

    // statement binding: a proof of a smaller trace verified with the batch's log_n; the zero batch
    push("b_degree_bits_unbound", "reject", "uni-stark 0.4.3 verify reads degree_bits from the PROOF; log_n is only an upper bound for the PCS",
         "honest 2-VU trace (256 rows) verified by the verifier configured for log_n = 19 (B = 4096)".into(), honest.clone(), Some(19));
    let zero = [forge.zero_rows.clone(), forge.zero_rows.clone()].concat();
    push("b_zero_batch_as_any_statement", "reject", "no public values: the verifier is not given (a, b, y16); any satisfying trace is a proof of every statement",
         "two zero VUs (a = b = 0, y16 = 0) proved and verified as if they were the two real VUs".into(), zero, None);
    let _ = idx;
    out
}

const COL_INV_NAME: &str = "vu.inv";

fn run_backend<B: Backend>(forge: &Forge, cs: &[Case], fri: FriParams) -> Vec<Value>
where
    Val<B::SC>: PrimeField64 + Send + Sync,
{
    let mut out = vec![];
    for c in cs {
        let t0 = Instant::now();
        let failing = forge.failing::<Val<B::SC>>(&c.rows);
        let trace: RowMajorMatrix<Val<B::SC>> = forge.trace(&c.rows);
        let log_n = trace.height().trailing_zeros() as usize;
        let proof = stark::prove_with::<B, _>(&forge.air, trace, fri);
        let res = stark::verify_with::<B, _>(&forge.air, &proof, c.verify_log_n.unwrap_or(log_n), fri);
        let accepted = res.is_ok();
        let status = match (c.expected, accepted) {
            ("reject", true) => "FORGED",
            ("reject", false) => "UNSAT",
            ("accept", true) | ("accept_by_design", true) => "ok",
            _ => "COMPLETENESS_BUG",
        };
        let mut by_name: BTreeMap<String, usize> = BTreeMap::new();
        for (_, n) in &failing { *by_name.entry(n.clone()).or_default() += 1; }
        eprintln!("[{}] {:24} expected={:16} verify={:?} evaluator_failing={} -> {status} ({:.1}s)", forge.kind.name(), c.id, c.expected, res, failing.len(), t0.elapsed().as_secs_f64());
        out.push(json!({
            "id": c.id, "field": forge.kind.name(), "expected": c.expected, "mechanism": c.mechanism, "mutation": c.mutation,
            "rows_real": c.rows.len(), "log_n_proved": log_n, "log_n_verified": c.verify_log_n.unwrap_or(log_n),
            "evaluator": {"failing_total": failing.len(), "by_constraint": by_name, "first": failing.iter().take(6).map(|(r, n)| json!([r, n])).collect::<Vec<_>>()},
            "verifier": {"accepted": accepted, "error": res.err().map(|e| format!("{e:?}"))},
            "fri": {"log_blowup": fri.log_blowup, "num_queries": fri.num_queries, "pow_bits": fri.proof_of_work_bits},
            "status": status,
        }));
    }
    out
}

fn battery(args: &[String]) {
    if cfg!(debug_assertions) { eprintln!("WARNING: debug build -- uni-stark's prover asserts constraints and will panic on forged traces; use --release"); }
    let root = PathBuf::from(arg(args, "--root").unwrap_or_else(|| "fixtures/bench-instances/v1".into()));
    let out = arg(args, "--out").or_else(|| std::env::var("RESEARCH_RUN_DIR").ok()).unwrap_or_else(|| ".".into());
    let mut fri = DEFAULT_FRI;
    if let Some(q) = arg(args, "--queries") { fri.num_queries = q.parse().unwrap(); }
    let fields: Vec<FieldKind> = match arg(args, "--field").as_deref().unwrap_or("both") {
        "goldilocks" => vec![FieldKind::Goldilocks],
        "babybear" => vec![FieldKind::BabyBear],
        _ => vec![FieldKind::Goldilocks, FieldKind::BabyBear],
    };
    fs::create_dir_all(&out).unwrap();
    let vus = real_vus(&root, 2);
    let mut results = vec![];
    for kind in fields {
        let forge = Forge::new(kind);
        let cs = cases(&forge, &vus);
        let r = match kind {
            FieldKind::Goldilocks => run_backend::<GoldilocksBackend>(&forge, &cs, fri),
            FieldKind::BabyBear => run_backend::<BabyBearBackend>(&forge, &cs, fri),
        };
        results.extend(r);
    }
    let forged: Vec<&Value> = results.iter().filter(|r| r["status"] == "FORGED").collect();
    let summary = json!({
        "schema": "redteam-vu-b/battery/v1",
        "target": "verity-direct ChainAir (Candidate B full VU, PROTOCOL.md 12), Plonky3 uni-stark 0.4.3-succinct, Keccak-256, FRI",
        "source_vus": "vu-k1536-neg bases 0 and 1 with their correct words",
        "run_id": std::env::var("RESEARCH_RUN_ID").ok(),
        "n_cases": results.len(),
        "forged": forged.iter().map(|r| format!("{}/{}", r["field"].as_str().unwrap(), r["id"].as_str().unwrap())).collect::<Vec<_>>(),
        "cases": results,
    });
    fs::write(format!("{out}/vu_battery_b.json"), serde_json::to_string_pretty(&summary).unwrap()).unwrap();
    eprintln!("wrote {out}/vu_battery_b.json: {} cases, {} FORGED", summary["n_cases"], forged.len());
}

// ---------------------------------------------------------------------------------------------------------------
// Challenger audit
// ---------------------------------------------------------------------------------------------------------------

fn chi2(counts: &[u64], n: u64) -> f64 {
    let e = n as f64 / counts.len() as f64;
    counts.iter().map(|&c| (c as f64 - e).powi(2) / e).sum()
}

fn stats(name: &str, vals: &[u64], p: u128) -> Value {
    let n = vals.len() as u64;
    let zeros = vals.iter().filter(|&&v| v == 0).count();
    let mut low = vec![0u64; 256];
    let mut buckets = vec![0u64; 16];
    let mut ge_p = 0usize;
    for &v in vals {
        low[(v & 0xff) as usize] += 1;
        buckets[((v as u128) * 16 / p) as usize] += 1;
        if v as u128 >= p { ge_p += 1; }
    }
    let c_low = chi2(&low, n);
    let c_b = chi2(&buckets, n);
    json!({
        "challenger": name, "samples": n, "zeros": zeros, "out_of_range": ge_p,
        "chi2_low_byte_256": c_low, "chi2_low_byte_999_quantile": 330.5,
        "chi2_16_buckets_of_[0,p)": c_b, "chi2_16_999_quantile": 37.7,
        "uniform": zeros <= 1 && ge_p == 0 && c_low < 330.5 && c_b < 37.7,
    })
}

fn challenger(args: &[String]) {
    let out = arg(args, "--out").or_else(|| std::env::var("RESEARCH_RUN_DIR").ok()).unwrap_or_else(|| ".".into());
    let n: usize = arg(args, "--samples").map(|s| s.parse().unwrap()).unwrap_or(100_000);
    fs::create_dir_all(&out).unwrap();
    let mut report = vec![];
    // the fork (Goldilocks), as stark.rs builds it
    {
        let mut ch = FixedSerializingChallenger64::<Goldilocks, HashChallenger<u8, Keccak256Hash, 32>>::from_hasher(vec![], Keccak256Hash {});
        let vals: Vec<u64> = (0..n).map(|_| { let x: Goldilocks = ch.sample(); x.as_canonical_u64() }).collect();
        report.push(stats("FixedSerializingChallenger64<Goldilocks> (backends/direct/src/challenger.rs)", &vals, Goldilocks::ORDER_U64 as u128));
    }
    // BabyBear: upstream SerializingChallenger32 as stark.rs uses it
    {
        let mut ch = SerializingChallenger32::<BabyBear, HashChallenger<u8, Keccak256Hash, 32>>::from_hasher(vec![], Keccak256Hash {});
        let vals: Vec<u64> = (0..n).map(|_| { let x: BabyBear = ch.sample(); x.as_canonical_u64() }).collect();
        report.push(stats("SerializingChallenger32<BabyBear> (p3-challenger 0.4.3-succinct, unmodified)", &vals, BabyBear::ORDER_U64 as u128));
    }
    // the upstream 64-bit challenger: the bug (release: every sample is zero; debug: shift-overflow panic)
    if !cfg!(debug_assertions) {
        let mut ch = SerializingChallenger64::<Goldilocks, HashChallenger<u8, Keccak256Hash, 32>>::from_hasher(vec![], Keccak256Hash {});
        let vals: Vec<u64> = (0..1000).map(|_| { let x: Goldilocks = ch.sample(); x.as_canonical_u64() }).collect();
        report.push(stats("UPSTREAM SerializingChallenger64<Goldilocks> (p3-challenger 0.4.3-succinct, the bug)", &vals, Goldilocks::ORDER_U64 as u128));
    }
    // extension sampling through the fork: the 2 coordinates of Goldilocks^2 are independent draws
    {
        use p3_field::extension::BinomialExtensionField;
        use p3_field::AbstractExtensionField;
        let mut ch = FixedSerializingChallenger64::<Goldilocks, HashChallenger<u8, Keccak256Hash, 32>>::from_hasher(vec![], Keccak256Hash {});
        let mut c0 = vec![]; let mut c1 = vec![];
        for _ in 0..n / 2 {
            let x: BinomialExtensionField<Goldilocks, 2> = ch.sample();
            let s: &[Goldilocks] = x.as_base_slice();
            c0.push(s[0].as_canonical_u64()); c1.push(s[1].as_canonical_u64());
        }
        report.push(stats("Fixed challenger, Goldilocks^2 coordinate 0", &c0, Goldilocks::ORDER_U64 as u128));
        report.push(stats("Fixed challenger, Goldilocks^2 coordinate 1", &c1, Goldilocks::ORDER_U64 as u128));
        let same = c0.iter().zip(&c1).filter(|(a, b)| a == b).count();
        report.push(json!({"check": "ext coordinates equal", "count": same, "of": n / 2}));
    }
    let doc = json!({"schema": "redteam-vu-b/challenger/v1", "run_id": std::env::var("RESEARCH_RUN_ID").ok(), "release_build": !cfg!(debug_assertions), "report": report});
    fs::write(format!("{out}/challenger_audit.json"), serde_json::to_string_pretty(&doc).unwrap()).unwrap();
    println!("{}", serde_json::to_string_pretty(&doc).unwrap());
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    match args.get(1).map(|s| s.as_str()) {
        Some("battery") => battery(&args),
        Some("challenger") => challenger(&args),
        _ => { eprintln!("usage: redteam-vu-b battery|challenger ..."); std::process::exit(2); }
    }
}
